#include <iostream>

template <typename F>
void g() {
    F(); // Call the callable object
}

int main() {
    auto lambda = []() { std::cout << "Lambda called!" << std::endl; };
    g<decltype(lambda)>(lambda); // Pass lambda as template argument
    g<decltype([](){})>(); // Pass unnamed lambda directly
    return 0;
}
